class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        in_degree = [0] * n
        for u, v in edges:
            in_degree[v] += 1
        zero_in = [i for i in range(n) if in_degree[i] == 0]
        return zero_in[0] if len(zero_in) == 1 else -1

class Solution {
public:
    int findChampion(int n, vector<vector<int>>& edges) {
        vector<int> in_deg(n, 0);
        for (auto& e : edges) in_deg[e[1]]++;
        int champ = -1;
        for (int i = 0; i < n; i++) {
            if (in_deg[i] == 0) {
                if (champ != -1) return -1;
                champ = i;
            }
        }
        return champ;
    }
};

class Solution {
    public int findChampion(int n, int[][] edges) {
        int[] inDeg = new int[n];
        for (int[] e : edges) inDeg[e[1]]++;
        int champ = -1;
        for (int i = 0; i < n; i++) {
            if (inDeg[i] == 0) {
                if (champ != -1) return -1;
                champ = i;
            }
        }
        return champ;
    }
}

/**
 * @param {number} n
